import { Heatmap } from "march/charts"
import { Button } from "march/ui"

// su içme alışkanlığı takvimi: "Bir bardak" bugüne bir bardak ekler, bugünün hücresi koyulaşır
const TODAY = new Date(2026, 10, 20)
const start = Array.from({ length: 8 * 7 }, (_, i) => { const d = new Date(TODAY); d.setDate(TODAY.getDate() - i); return { gun: d, bardak: i === 0 ? 0 : (i * 5) % 9 } })

export function WaterHabit() {
  let $days = start
  const drink = () => { $days = $days.map((d, i) => (i === 0 ? { ...d, bardak: d.bardak + 1 } : d)) }
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Button on:click={drink}>💧 Bir bardak</Button>
      <span>Bugün: {() => $days[0].bardak} bardak</span>
    </div>
    <Heatmap data={() => $days} x="gun" value="bardak" calendar={{ weeks: 8 }} end={TODAY} max={8} valueLabel="Bardak" animate title="Su takvimi" />
  </div>
}

import { Heatmap } from "march/charts"
import { Card, Segmented } from "march/ui"

// sunucu yükü: bölge × saat, ortam seçilir; en yoğun hücreye tıklamak onu adıyla gösterir
const REGIONS = ["İstanbul", "Frankfurt", "Virginia", "Singapur"]
const load = (env: string) => REGIONS.flatMap((bolge, r) => Array.from({ length: 12 }, (_, i) => ({
  saat: i * 2, bolge, yuk: Math.round(30 + 50 * Math.max(0, Math.sin(((i * 2 - r * 5) / 24) * Math.PI)) + ((i * 7 + r * 3) % 11) * (env === "prod" ? 3 : 1)),
})))

export function ServerLoad() {
  let $env = "prod"
  let $cell = "Bir hücre seç"
  return <Card title="Sunucu yükü (%)" actions={[<Segmented size="sm" bind:value={$env} aria-label="Ortam" options={[{ value: "prod", label: "Canlı" }, { value: "staging", label: "Deneme" }]} />]}>
    <Heatmap data={() => load($env)} x="saat" y="bolge" value="yuk" xFormat={(h: number) => `${h}:00`} yDomain={REGIONS} max={100} levels={6}
      format={(v: number) => `%${v}`} valueLabel="Yük" animate="out" title="Sunucu yükü" onSelect={(c: { x: unknown; y: unknown; value: number | null }) => { $cell = `${c.y} ${c.x}:00 · %${c.value}` }} />
    <p sx={{ text: "sm", color: "muted" }}>{() => $cell}</p>
  </Card>
}

import { Heatmap } from "march/charts"
import { Button, Card } from "march/ui"

// Heatmap'in bütün özellikleri: data (sinyal), x, y, value, calendar ({ weeks }), end, xFormat, yFormat, xDomain,
// yDomain, format, levels, max, cell, valueLabel, tooltip, onSelect, animate, title, description, empty, class
const DAYS = ["Pzt", "Sal", "Çar", "Per", "Cum"]
const make = (k: number) => DAYS.flatMap((gun, d) => [9, 12, 15, 18].map((saat) => ({ gun, saat, kisi: ((d * 7 + saat + k * 5) % 13) })))
const END = new Date(2026, 10, 20)

export function HeatmapLab() {
  let $k = 1
  let $picked = "—"
  let $empty = false
  return <div sx={{ flex: "col", gap: 3 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Button class="lab-next" size="sm" on:click={() => { $k++ }}>Yeni hafta</Button>
      <Button class="lab-empty" size="sm" variant="ghost" on:click={() => { $empty = !$empty }}>Boşalt / geri getir</Button>
      <span class="lab-picked">Seçilen: {() => $picked}</span>
    </div>
    <Heatmap class="lab-grid" data={() => ($empty ? [] : make($k))} x="saat" y="gun" value="kisi" xDomain={$empty ? undefined : [9, 12, 15, 18]} yDomain={$empty ? undefined : DAYS}
      xFormat={(h: number) => `${h}:00`} yFormat={(g: string) => g.toUpperCase()} format={(v: number) => `${v} kişi`} levels={4} max={12} cell={28}
      valueLabel="Kişi" animate tooltip={(c: { x: unknown; y: unknown; value: number | null }) => `${c.y} ${c.x}:00 → ${c.value} kişi`} onSelect={(c: { x: unknown; y: unknown; value: number | null }) => { $picked = `${c.y} ${c.x}:00` }}
      title="Toplantı odası" description="Gün ve saate göre oda kullanımı" empty="Kayıt yok" />
    <Card m:theme="night">
      <Heatmap class="lab-cal" data={() => make($k).map((r, i) => { const d = new Date(END); d.setDate(END.getDate() - i); return { x: d, value: r.kisi } })}
        calendar={{ weeks: 4 }} end={END} levels={5} title="Takvim" />
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { HeatmapLab } from "./HeatmapLab.tsx"

// HeatmapLab'in testleri: kaydedince Testler sekmesinde çalışır
test("beş gün × dört saat: yirmi hücre, başlık ve açıklama", () => {
  const s = renderTest(() => <HeatmapLab />)
  const grid = s.get(".lab-grid")!
  expect(grid.querySelectorAll(".m-heat-cell").length).toBe(20)
  expect(grid.querySelector("svg title")!.textContent).toBe("Toplantı odası")
  expect(grid.querySelector("svg desc")!.textContent).toBe("Gün ve saate göre oda kullanımı")
})

test("bir hücreye tıklamak onu seçer", async () => {
  const s = renderTest(() => <HeatmapLab />)
  s.get(".lab-grid .m-heat-cell")!.dispatchEvent(new MouseEvent("click", { bubbles: true }))
  await s.flush()
  expect(s.get(".lab-picked")!.textContent).not.toBe("Seçilen: —")
})

test("veri boşalınca boş metni görünür", async () => {
  const s = renderTest(() => <HeatmapLab />)
  await s.click(".lab-empty")
  expect(s.sees("Kayıt yok")).toBe(true)
})

test("takvim dört haftayı çizer", () => {
  const s = renderTest(() => <HeatmapLab />)
  expect(s.get(".lab-cal")!.querySelectorAll(".m-heat-cell").length).toBeGreaterThan(20)
})
